<?php
require 'includes/functions.php';$u=auth();$count=(int)q('SELECT COUNT(*) FROM orders WHERE user_id=?',[$u['id']])->fetchColumn();$pages=max(1,(int)ceil($count/15));$page=max(1,min($pages,(int)($_GET['page']??1)));$orders=q('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 15 OFFSET '.(($page-1)*15),[$u['id']])->fetchAll();require 'includes/header.php';
?>
<div class="page-heading"><h1><?=e(t('คำสั่งซื้อของฉัน'))?></h1><p><?=e(t('ประวัติการซื้อ การชำระเงิน และการติดตามพัสดุ'))?></p></div>
<?php if(!$orders): ?><section class="empty"><h2><?=e(t('ยังไม่มีคำสั่งซื้อ'))?></h2><a class="button" href="<?=url('products.php')?>"><?=e(t('เลือกดูสินค้า'))?></a></section><?php endif ?>
<div class="order-list"><?php foreach($orders as $o): ?><article class="panel order-card"><div class="order-card-heading"><h2><a href="<?=url('order_detail.php?id='.$o['id'])?>">BP-<?=sprintf('%06d',$o['id'])?></a></h2><time><?=e($o['created_at'])?></time></div><div class="order-badges"><?=order_badge($o)?> <?=payment_badge($o)?></div><ul><?php foreach(q('SELECT name,quantity FROM order_items WHERE order_id=?',[$o['id']]) as $item): ?><li><?=e(localized_name($item))?> × <?=(int)$item['quantity']?></li><?php endforeach ?></ul><p><?=payment_method_label($o)?></p><p><?=e(t('สินค้า'))?> <?=money($o['subtotal'])?> <?=e(t('· ค่าจัดส่ง'))?> <?=money($o['shipping'])?></p><?php if(cents($o['product_discount']??0)+cents($o['coupon_discount']??0)>0): ?><p><?=e(t('ส่วนลดสินค้าและคูปอง −'))?> <?=money((cents($o['product_discount']??0)+cents($o['coupon_discount']??0))/100)?></p><?php endif ?><p><strong><?=e(t('ยอดรวม'))?> <?=money($o['total'])?></strong></p><?php if($o['tracking_number']): ?><p><?=e($o['carrier'])?> · <?=e($o['tracking_number'])?></p><?php endif ?><a class="button secondary" href="<?=url('order_detail.php?id='.$o['id'])?>"><?=e(t('รายละเอียด / สลิป / ติดตามสถานะ'))?></a></article><?php endforeach ?></div>
<div class="pagination"><?php for($number=1;$number<=$pages;$number++): ?><a class="<?=$number===$page?'selected':''?>" href="?page=<?=$number?>"><?=$number?></a><?php endfor ?></div>
<?php require 'includes/footer.php'; ?>
